#!/usr/bin/env python3
'''Scoped CPU check for K-ALG-013 handoff protocol.

This deterministic model checks source-prefix arithmetic, target coverage,
token readiness, commit/consume ordering, atomic reservation and output
visibility. It is not a GPU visibility, network or SLO measurement.
'''
from typing import Iterable, List, Tuple

Interval = Tuple[int, int]

class ProtocolError(Exception):
    pass

def intervals_cover(ranges: Iterable[Interval], start: int, end: int) -> bool:
    if start > end:
        return False
    if start == end:
        return True
    cursor = start
    for a, b in sorted(ranges):
        if a < start or b > end or a > b:
            return False
        if b <= cursor:
            continue
        if a > cursor:
            return False
        if b > cursor:
            cursor = b
        if cursor >= end:
            return True
    return cursor >= end

def prefill_pairs(n: int, b: int) -> int:
    if n < 0 or b < 0 or b > n:
        raise ValueError('invalid prefix')
    return n * (n + 1) // 2 - b * (b + 1) // 2

def handoff_times(p_wait: int, acquire: int, prefill: int, transfer_tail: int,
                  convert: int, d_queue: int, d_exec: int, output_send: int) -> dict:
    first_internal = p_wait + acquire + prefill
    state_ready = first_internal + transfer_tail + convert + d_queue
    first_early = first_internal + output_send
    first_gated = state_ready + output_send
    second = max(first_internal, state_ready) + d_exec + output_send
    return {
        'first_internal': first_internal,
        'state_ready': state_ready,
        'first_early': first_early,
        'first_gated': first_gated,
        'second': second,
        'early_interval': second - first_early,
        'gated_interval': second - first_gated,
    }

def first_token_route(n: int, h: int, adapter_ok: bool,
                      have_token: bool, have_logits: bool,
                      full_prefix_valid: bool) -> str:
    if n <= 0:
        return 'REJECT_EMPTY'
    if not adapter_ok:
        return 'REJECT_IDENTITY'
    if h < 0 or h > n:
        return 'REJECT_RANGE'
    if have_token:
        return 'EXISTING_TOKEN'
    if have_logits:
        return 'VALID_LOGITS'
    if h == n:
        if full_prefix_valid:
            return 'RECOVER_LAST_ROW'
        return 'REJECT_STATE'
    return 'PREFILL_SUFFIX'

class HandoffProtocol:
    def __init__(self, n: int, h: int, layers: int, generation: int):
        if n < 0 or h < 0 or h > n or layers <= 0:
            raise ValueError('invalid protocol bounds')
        self.n = n
        self.h = h
        self.layers = layers
        self.g = generation
        self.token_ready = False
        self.token = None
        self.committed = None
        self.ranges = {i: [] for i in range(layers)}
        self.decode_started = False

    def mark_token_ready(self, token: str) -> str:
        if self.token_ready:
            if token == self.token:
                return 'DUP_TOKEN'
            raise ProtocolError('different token for ready request')
        self.token_ready = True
        self.token = token
        return 'TOKEN_READY'

    def complete_layer_range(self, layer: int, a: int, b: int, g: int) -> str:
        if g != self.g:
            raise ProtocolError('stale generation')
        if layer not in self.ranges:
            raise ProtocolError('bad layer')
        if a < 0 or b > self.n or a > b or a < self.h:
            raise ProtocolError('range outside target missing prefix')
        self.ranges[layer].append((a, b))
        return 'RANGE_DONE'

    def all_layers_cover(self) -> bool:
        return all(intervals_cover(self.ranges[i], self.h, self.n)
                   for i in range(self.layers))

    def commit(self, g: int) -> str:
        if g != self.g:
            raise ProtocolError('stale commit')
        if not self.all_layers_cover():
            raise ProtocolError('early commit: missing layer range')
        if self.committed == g:
            return 'DUP_COMMIT'
        self.committed = g
        return 'COMMITTED'

    def start_decode(self, g: int) -> str:
        if g != self.g:
            raise ProtocolError('stale decode')
        if not self.token_ready:
            raise ProtocolError('early consume: token not ready')
        if self.committed != g:
            raise ProtocolError('early consume: target not committed')
        if not self.all_layers_cover():
            raise ProtocolError('early consume: missing KV')
        self.decode_started = True
        return self.token

class TargetPool:
    def __init__(self, total: int, active: int, receiving: int):
        if min(total, active, receiving) < 0 or active + receiving > total:
            raise ValueError('invalid capacity')
        self.total = total
        self.active = active
        self.receiving = receiving
        self.reservations = {}

    def free(self) -> int:
        return self.total - self.active - self.receiving

    def estimate(self, need: int) -> bool:
        if need < 0:
            raise ValueError('negative need')
        return need <= self.free()

    def reserve(self, need: int, tag: str) -> str:
        if tag in self.reservations:
            return tag
        if not self.estimate(need):
            raise ProtocolError('insufficient target capacity')
        self.receiving += need
        self.reservations[tag] = need
        return tag

    def release(self, tag: str) -> int:
        if tag not in self.reservations:
            return 0
        need = self.reservations.pop(tag)
        self.receiving -= need
        return need

class OutputLedger:
    def __init__(self, policy: str):
        if policy not in ('EARLY', 'GATED'):
            raise ValueError('bad policy')
        self.policy = policy
        self.visible = {}

    def dispatch(self, logical_index: int, token: str, timestamp: int,
                 committed: bool) -> bool:
        if logical_index in self.visible:
            return False
        if self.policy == 'GATED' and not committed:
            raise ProtocolError('gated output before target commit')
        self.visible[logical_index] = (token, timestamp)
        return True

class FirstTokenLedger:
    def __init__(self):
        self.tickets = {}
        self.sample_tokens = {}
        self.samples = 0

    def sample_once(self, request: str, position: int, token: str) -> str:
        key = (request, position)
        if key in self.sample_tokens:
            if self.sample_tokens[key] != token:
                raise ProtocolError('different sample for same ticket')
            return self.sample_tokens[key]
        self.samples += 1
        self.sample_tokens[key] = token
        self.tickets[(request, 0)] = token
        return token

    def emit_existing(self, request: str, position: int, token: str) -> str:
        key = (request, position)
        if key in self.sample_tokens and self.sample_tokens[key] != token:
            raise ProtocolError('existing token conflicts with sample state')
        self.tickets[(request, 0)] = token
        return token

def main() -> int:
    print('K-ALG-013 scoped CPU check: protocol events and arithmetic; no GPU measurement')

    b_tok = 2 * 32 * 8 * 128 * 2
    assert b_tok == 131072
    n = 4096
    h = 1024
    assert (n - h) * b_tok == 384 * 1024 * 1024
    assert prefill_pairs(4096, 0) == 8390656
    assert prefill_pairs(4096, 2048) == 6292480
    assert prefill_pairs(4096, 4096) == 0
    print('prefix arithmetic: target suffix=%d MiB, source q at b=0=%d, b=2048=%d' %
          ((n - h) * b_tok // (1024 * 1024), n, n - 2048))

    chunks = [(h, 2048), (2048, 3072), (3072, n)]
    assert intervals_cover(chunks, h, n)
    assert not intervals_cover(chunks[:-1], h, n)
    for layer in range(2):
        assert intervals_cover([(h, n)], h, n)
    print('coverage: complete three-block range accepted; missing final block rejected')

    t = handoff_times(10, 0, 80, 25, 5, 10, 10, 5)
    assert t['first_internal'] == 90
    assert t['state_ready'] == 130
    assert t['first_early'] == 95
    assert t['first_gated'] == 135
    assert t['second'] == 145
    assert t['early_interval'] == 50
    assert t['gated_interval'] == 10
    print('timeline: early ttft=%d interval=%d; gated ttft=%d interval=%d; second=%d' %
          (t['first_early'], t['early_interval'], t['first_gated'],
           t['gated_interval'], t['second']))

    assert first_token_route(4096, 4096, True, True, False, True) == 'EXISTING_TOKEN'
    assert first_token_route(4096, 4096, True, False, True, True) == 'VALID_LOGITS'
    assert first_token_route(4096, 4096, True, False, False, True) == 'RECOVER_LAST_ROW'
    assert first_token_route(4096, 1024, True, False, False, True) == 'PREFILL_SUFFIX'
    assert first_token_route(0, 0, True, False, False, True) == 'REJECT_EMPTY'
    assert first_token_route(10, 11, True, False, False, True) == 'REJECT_RANGE'
    assert first_token_route(10, 10, False, False, False, True) == 'REJECT_IDENTITY'
    assert first_token_route(10, 10, True, False, False, False) == 'REJECT_STATE'
    print('first-token routes: existing, logits, recover, prefill, and invalid states classified')

    ledger = FirstTokenLedger()
    assert ledger.sample_once('R', 4096, 'A') == 'A'
    assert ledger.sample_once('R', 4096, 'A') == 'A'
    assert ledger.samples == 1
    assert ledger.emit_existing('Q', 4096, 'B') == 'B'
    assert ledger.samples == 1
    print('sample ledger: duplicate sample returns original; existing token does not resample')

    ok = HandoffProtocol(8, 4, 2, 7)
    ok.mark_token_ready('y8')
    for layer in range(2):
        ok.complete_layer_range(layer, 4, 6, 7)
        ok.complete_layer_range(layer, 6, 8, 7)
    ok.commit(7)
    assert ok.start_decode(7) == 'y8'
    print('positive protocol: token ready + two-layer coverage + commit -> decode consumes y8')

    bad_commit = HandoffProtocol(8, 4, 2, 70)
    bad_commit.mark_token_ready('y8')
    early_commit_detected = False
    try:
        bad_commit.commit(70)
    except ProtocolError:
        early_commit_detected = True
    assert early_commit_detected
    assert not bad_commit.all_layers_cover()
    print('negative control detected: early TARGET_COMMIT rejected by missing layer coverage')

    bad_consume = HandoffProtocol(8, 4, 2, 71)
    bad_consume.mark_token_ready('y8')
    early_consume_detected = False
    try:
        bad_consume.start_decode(71)
    except ProtocolError:
        early_consume_detected = True
    assert early_consume_detected
    print('negative control detected: early decode consume rejected before target commit')

    full = HandoffProtocol(8, 8, 2, 9)
    full.mark_token_ready('y8')
    assert full.all_layers_cover()
    full.commit(9)
    assert full.start_decode(9) == 'y8'
    print('full-prefix recovery path: empty M is covered, token still gates decode')

    pool = TargetPool(10, 4, 3)
    before = pool.receiving
    estimates = [pool.estimate(2), pool.estimate(4), pool.estimate(1)]
    assert estimates == [True, False, True]
    assert pool.receiving == before
    pool.reserve(2, 'chosen')
    assert pool.receiving == 5 and pool.free() == 1
    capacity_detected = False
    try:
        pool.reserve(4, 'bad')
    except ProtocolError:
        capacity_detected = True
    assert capacity_detected and 'bad' not in pool.reservations
    print('reservation: estimates are side-effect free; selected reservation consumes once; overcommit rejected')

    early = OutputLedger('EARLY')
    assert early.dispatch(0, 'y8', 95, False) is True
    assert early.dispatch(0, 'y8', 96, False) is False
    assert early.visible[0] == ('y8', 95)

    gated = OutputLedger('GATED')
    output_detected = False
    try:
        gated.dispatch(0, 'y8', 95, False)
    except ProtocolError:
        output_detected = True
    assert output_detected
    assert gated.dispatch(0, 'y8', 135, True) is True
    assert gated.dispatch(0, 'y8', 136, True) is False
    print('output ledger: early send before commit allowed; gated send before commit rejected; duplicates suppressed')

    print('PASS: scoped CPU invariants and injected commit/consume/output faults detected')
    return 0

if __name__ == '__main__':
    raise SystemExit(main())
